window.AUTH=window.AUTH||{};window.AUTH["22-529"]={"d":"22-529","id":"2023/22-529","n":"Cantero v. Bank of America, N.A.","briefs":[{"k":"petitioner","label":"Brief of petitioners Alex Cantero, et al.","date":"2023-12-08","url":"https://www.supremecourt.gov/DocketPDF/22/22-529/292905/20231208184157268_Cantero%20Opening%20Brief%20and%20Appendix.pdf","side":"pet","n":0},{"k":"united-states","label":"Brief amicus curiae of United States supporting vacatur","date":"2023-12-15","url":"https://www.supremecourt.gov/DocketPDF/22/22-529/293528/20231215173321886_22-529%20Cantero%20et%20al%20v.%20Bank%20of%20America.pdf","side":"pet","n":46},{"k":"respondent","label":"Brief of respondent Bank of America, N.A.","date":"2024-01-18","url":"https://www.supremecourt.gov/DocketPDF/22/22-529/298061/20240118141045917_Cantero%20-%20Brief%20for%20Respondent.pdf","side":"res","n":55},{"k":"reply","label":"Reply of petitioners Alex Cantero, et al.","date":"2024-02-16","url":"https://www.supremecourt.gov/DocketPDF/22/22-529/300761/20240216101807181_Cantero%20v.%20Bank%20of%20America%20-%20Reply%20Brief%20of%20Petitioners.pdf","side":"pet","n":38}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r29_0861.pdf","tr":true,"items":[{"t":"case","label":"Anderson Nat’l Bank v. Luckett","cite":"321 U.S. 233","y":1944,"id":"scdb/1943-064","sc":1,"op":3,"sum":"A statute of Kentucky sets up a comprehensive scheme for the administration of abandoned bank deposits. Upon a report by the bank and notice to the depositor, and with an opportunity for either to be heard, the State takes into its protective custody bank accounts which, having been inactive for at least ten years if demand accounts or for at least twenty-five years if non-demand, the statute declares to be …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 31, 33","2":"24, 26, 42","3":"8"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Atherton v. FDIC","cite":"519 U.S. 213","y":1997,"id":"1996/95-928","sc":1,"sum":"The unanimous Court concluded that \"state law sets the standard of conduct as long as the state standard is stricter than that of the federal statute.\" The opinion by Justice Stephen Breyer held that the federal \"gross negligence\" statute was only intended to set a \"floor\" or minimum standard for state laws governing negligent conduct.","sumSrc":"Oyez","by":{"1":"27, 32","2":"25"}},{"t":"case","label":"Barnett Bank v. Nelson","cite":"517 U.S. 25","y":1996,"id":"1995/94-1837","sc":1,"op":37,"ar":35,"sum":"The Federal Statute pre-empts the State Statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 13, 14, 17, 28-30","2":"2-3, 6-7, 12, 15-23, 26-28, 31, 33-41, 45-46","3":"2, 6, 19"}},{"t":"case","label":"Biestek v. Berryhill","cite":"139 S. Ct. 1148","y":2019,"id":"2018/17-1184","sc":1,"sum":"A vocational expert’s refusal to provide private market-survey data during a Social Security disability benefits hearing upon the applicant’s request does not categorically preclude the testimony from counting as “substantial evidence” in federal court under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15"}},{"t":"case","label":"Cuomo v. Clearing House Ass’n","cite":"557 U.S. 519","y":2009,"id":"2008/08-453","sc":1,"ar":1,"sum":"The Court found that state officials are not precluded from regulating and enforcing banking activities governed by the Office of the Comptroller.","sumSrc":"Oyez","by":{"1":"2, 18, 20, 26, 32","2":"6, 20-21, 26, 32, 42-43","3":"1, 5, 8, 9, 18"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Davis v. Elmira Sav. Bank","cite":"161 U.S. 275","y":1896,"id":"scdb/1895-136","sc":1,"sum":"Section 130 of chapter 689 of the laws of New York of 1892, providing for the payment by the receiver of an insolvent bank, in the first place, of deposits in the bank by savings banks, when applied to an insolvent national bank, is in conflict with § 5236 of the Revised Statutes of the United States, directing the Comptroller of the Currency to make ratable dividends of the money paid over to him by such receiver, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"27","2":"22"}},{"t":"case","label":"DeBoer v. Mellon Mortg. Co.","cite":"64 F.3d 1171","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/64/1171/","by":{"1":"7"}},{"t":"case","label":"Director of Revenue v. CoBank ACB","cite":"531 U.S. 316","y":2001,"id":"2000/99-1792","sc":1,"sum":"The Court held that banks for cooperatives are subject to taxation. Justice Thomas wrote for the Court that nothing in the 1985 amendments to the Farm Credit Act indicated a repeal of the previous express approval of state taxation and that the structure of the Act indicated by negative implication that banks for cooperatives were not entitled to immunity.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"First Agric. Nat’l Bank v. State Tax Comm’n","cite":"392 U.S. 339","y":1968,"id":"1967/755","sc":1,"sum":"Massachusetts sales tax (which by its terms must be passed on to the purchaser) and use tax are invalid as applied to national banks since such taxes are not among the only four specified methods of taxation in addition to taxes on real estate by which, under 12 U. S. C. § 548, Congress has permitted States to tax national banks. Pp. 339-348. - Mass. -, 229 N. E. 2d 245, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27, 28"}},{"t":"case","label":"First Nat’l Bank of San Jose v. California","cite":"262 U.S. 366","y":1923,"id":"scdb/1922-201","sc":1,"op":2,"sum":"Reasoning that customers “might well hesitate” to subject their deposits to “unusual” California law.","sumSrc":"opinion","by":{"1":"30, 31","2":"21, 24-25, 31","3":"8"}},{"t":"case","label":"First Nat’l Bank in St. Louis v. Missouri","cite":"263 U.S. 640","y":1924,"id":"scdb/1923-214","sc":1,"sum":"1. National banks are subject to state laws that do not interfere with the purposes of their creation, tend to destroy or impair their efficiency as federal agencies, of conflict with the laws of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18","2":"25-26, 42"}},{"t":"case","label":"Franklin Nat’l Bank of Franklin Square v. New York","cite":"347 U.S. 373","y":1954,"id":"scdb/1953-060","sc":1,"op":2,"sum":"Concluding that New York law interfered with ability to use “a particular label” that federal law “specifcally selected”.","sumSrc":"opinion","by":{"1":"31, 32","2":"5, 20, 23, 41-42"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"1":"33","2":"49","3":"17"}},{"t":"case","label":"Lusnak v. Bank of America, N.A.","cite":"883 F.3d 1185","y":2018,"url":"https://www.courtlistener.com/c/F.3d/883/1185/","ar":1,"by":{"1":"7","2":"34"}},{"t":"case","label":"McClellan v. Chipman","cite":"164 U.S. 347","y":1896,"id":"scdb/1896-035","sc":1,"op":2,"sum":"The provisions of §§ 96 and 98 of c. 157 of the Public Statutes of Massachusetts, invalidating preferences made by insolvent debtors and assignments or transfers made in contemplation of insolvency, do not conflict with the provisions containéd in Rev. Stat. §§ 5136 and 5137, relating to national banks and to mortgages of real estate made to them in good faith by way of security for debts previously contracted, and …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18","2":"25","3":"5"}},{"t":"case","label":"Nationsbank of North Carolina v. Variable Annuity Life Ins. Co.","cite":"513 U.S. 251","y":1995,"id":"1994/93-1612","sc":1,"sum":"Petitioner national bank and its brokerage subsidiary applied to the Comptroller of the Currency, charged by Congress with superintendence of national banks, to allow the subsidiary to act as an agent in the sale of annuities. Under the proposed plan, bank customers could purchase a \"variable annuity\"-which invests payments in a designated way and yields income that varies with investment performance-a \"fixed\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"United States v. Washington","cite":"596 U.S. 832","y":2022,"id":"2021/21-404","sc":1,"op":2,"sum":"Washington’s workers’ compensation law is unconstitutional under the Supremacy Clause because it facially discriminates against the Federal Government and does not fall within the scope of the federal waiver of immunity contained in 40 U. S. C. §3172.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26"}},{"t":"case","label":"Watters v. Wachovia Bank, N. A.","cite":"550 U.S. 1","y":2007,"id":"2006/05-1342","sc":1,"ar":2,"sum":"The Court ruled 5-3 that state-chartered operating subsidiaries of national banks are subject to regulation by the federal Office of the Comptroller of Currency and not by the states in which they are located.","sumSrc":"Oyez","by":{"1":"2, 19, 20","2":"2, 4, 6-7, 14, 21, 23-26, 31-33, 38, 42"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"1"}},{"t":"usc","label":"12 U.S.C. § 25b","url":"https://www.law.cornell.edu/uscode/text/12/25b","subs":["(a)(2)","(b)","(b)(1)","(b)(1)(B)","(b)(2)","(b)(3)","(b)(3)(A)","(c)","(d)","(b)(5)(A)"],"stext":{"head":"§25b. State law preemption standards for national banks and subsidiaries clarified","paras":[[0,"(a) Definitions"],[0,"For purposes of this section, the following definitions shall apply:"],[0,"(1) National bank"],[1,"The term \"national bank\" includes—"],[2,"(A) any bank organized under the laws of the United States; and"],[2,"(B) any Federal branch established in accordance with the International Banking Act of 1978 [12 U.S.C. 3101 et seq.]."],[0,"(2) State consumer financial laws"],[1,"The term \"State consumer financial law\" means a State law that does not directly or indirectly discriminate against national banks and that directly and specifically regulates the manner, content, or terms and conditions of any financial transaction (as may be authorized for national banks to engage in), or any account related thereto, with respect to a consumer."],[0,"(3) Other definitions"],[1,"The terms \"affiliate\", \"subsidiary\", \"includes\", and \"including\" have the same meanings as in section 1813 of this title."],[0,"(b) Preemption standard"],[0,"(1) In general"],[1,"State consumer financial laws are preempted, only if—"],[2,"(A) application of a State consumer financial law would have a discriminatory effect on national banks, in comparison with the effect of the law on a bank chartered by that State;"],[2,"(B) in accordance with the legal standard for preemption in the decision of the Supreme Court of the United States in Barnett Bank of Marion County, N. A. v. Nelson, Florida Insurance Commissioner, et al., 517 U.S. 25 (1996), the State consumer financial law prevents or significantly interferes with the exercise by the national bank of its powers; and any preemption determination under this subparagraph may be made by a court, or by regulation or order of the Comptroller of the Currency on a case-by-case basis, in accordance with applicable law; or"],[2,"(C) the State consumer financial law is preempted by a provision of Federal law other than title 62 of the Revised Statutes."],[0,"(2) Savings clause"],[1,"Title 62 of the Revised Statutes and section 371 of this title do not preempt, annul, or affect the applicability of any State law to any subsidiary or affiliate of a national bank (other than a subsidiary or affiliate that is chartered as a national bank)."],[0,"(3) Case-by-case basis"],[0,"(A) Definition"],[2,"As used in this section the term \"case-by-case basis\" refers to a determination pursuant to this section made by the Comptroller concerning the impact of a particular State consumer financial law on any national bank that is subject to that law, or the law of any other State with substantively equivalent terms."],[0,"(B) Consultation"],[2,"When making a determination on a case-by-case basis that a State consumer financial law of another State has substantively equivalent terms as one that the Comptroller is preempting, the Comptroller shall first consult with the Bureau of Consumer Financial Protection and shall take the views of the Bureau into account when making the determination."],[0,"(4) Rule of construction"],[1,"Title 62 of the Revised Statutes does not occupy the field in any area of State law."],[0,"(5) Standards of review"],[0,"(A) Preemption"],[2,"A court reviewing any determinations made by the Comptroller regarding preemption of a State law by title 62 of the Revised Statutes or section 371 of this title shall assess the validity of such determinations, depending upon the thoroughness evident in the consideration of the agency, the validity of the reasoning of the agency, the consistency with other valid determinations made by the agency, and other factors which the court finds persuasive and relevant to its decision."],[0,"(B) Savings clause"],[2,"Except as provided in subparagraph (A), nothing in this section shall affect the deference that a court may afford to the Comptroller in making determinations regarding the meaning or interpretation of title LXII of the Revised Statutes of the United States or other Federal laws."],[0,"(6) Comptroller determination not delegable"],[1,"Any regulation, order, or determination made by the Comptroller of the Currency under paragraph (1)(B) shall be made by the Comptroller, and shall not be delegable to another officer or employee of the Comptroller of the Currency."],[0,"(c) Substantial evidence"],[0,"No regulation or order of the Comptroller of the Currency prescribed under subsection (b)(1)(B), shall be interpreted or applied so as to invalidate, or otherwise declare inapplicable to a national bank, the provision of the State consumer financial law, unless substantial evidence, made on the record of the proceeding, supports the specific finding regarding the preemption of such provision in accordance with the legal standard of the decision of the Supreme Court of the United States in Barnett Bank of Marion County, N.A. v. Nelson, Florida Insurance Commissioner, et al., 517 U.S. 25 (1996)."],[0,"(d) Periodic review of preemption determinations"],[0,"(1) In general"],[1,"The Comptroller of the Currency shall periodically conduct a review, through notice and public comment, of each determination that a provision of Federal law preempts a State consumer financial law. The agency shall conduct such review within the 5-year period after prescribing or otherwise issuing such determination, and at least once during each 5-year period thereafter. After conducting the review of, and inspecting the comments made on, the determination, the agency shall publish a notice in the Federal Register announcing the decision to continue or rescind the determination or a proposal to amend the determination. Any such notice of a proposal to amend a determination and the subsequent resolution of such proposal shall comply with the procedures set forth in subsections (a) and (b) of section 43 of this title."],[0,"(2) Reports to Congress"],[1,"At the time of issuing a review conducted under paragraph (1), the Comptroller of the Currency shall submit a report regarding such review to the Committee on Financial Services of the House of Representatives and the Committee on Banking, Housing, and Urban Affairs of the Senate. The report submitted to the respective committees shall address whether the agency intends to continue, rescind, or propose to amend any determination that a provision of Federal law preempts a State consumer financial law, and the reasons therefor."],[0,"(e) Application of State consumer financial law to subsidiaries and affiliates"],[0,"Notwithstanding any provision of title 62 of the Revised Statutes or section 371 of this title, a State consumer financial law shall apply to a subsidiary or affiliate of a national bank (other than a subsidiary or affiliate that is chartered as a national bank) to the same extent that the State consumer financial law applies to any person, corporation, or other entity subject to such State law."],[0,"(f) Preservation of powers related to charging interest"],[0,"No provision of title 62 of the Revised Statutes shall be construed as altering or otherwise affecting the authority conferred by section 85 of this title for the charging of interest by a national bank at the rate allowed by the laws of the State, territory, or district where the bank is located, including with respect to the meaning of \"interest\" under such provision."],[0,"(g) Transparency of OCC preemption determinations"],[0,"The Comptroller of the Currency shall publish and update no less frequently than quarterly, a list of preemption determinations by the Comptroller of the Currency then in effect that identifies the activities and practices covered by each determination and the requirements and constraints determined to be preempted."],[0,"(h) Clarification of law applicable to nondepository institution subsidiaries and affiliates of national banks"],[0,"(1) Definitions"],[1,"For purposes of this subsection, the terms \"depository institution\", \"subsidiary\", and \"affiliate\" have the same meanings as in section 1813 of this title."],[0,"(2) Rule of construction"],[1,"No provision of title 62 of the Revised Statutes or section 371 of this title shall be construed as preempting, annulling, or affecting the applicability of State law to any subsidiary, affiliate, or agent of a national bank (other than a subsidiary, affiliate, or agent that is chartered as a national bank)."],[0,"(i) Visitorial powers"],[0,"(1) 1 In general"],[1,"In accordance with the decision of the Supreme Court of the United States in Cuomo v. Clearing House Assn., L. L. C. (129 S. Ct. 2710 (2009)), no provision of title 62 of the Revised Statutes which relates to visitorial powers or otherwise limits or restricts the visitorial authority to which any national bank is subject shall be construed as limiting or restricting the authority of any attorney general (or other chief law enforcement officer) of any State to bring an action against a national bank in a court of appropriate jurisdiction to enforce an applicable law and to seek relief as authorized by such law."],[0,"(j) Enforcement actions"],[0,"The ability of the Comptroller of the Currency to bring an enforcement action under title 62 of the Revised Statutes or section 45 of title 15 does not preclude any private party from enforcing rights granted under Federal or State law in the courts."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/25b?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":3,"head":"§25b. State law preemption standards for national banks and subsidiaries clarified","tname":"Banks and Banking","by":{"1":"3, 4, 8-14, 17, 22, 24, 25, 3, 21, 23, 24, 4-6, 13, 4, 13, 23, 32, 4, 6, 7, 9, 12-14, 17, 21, 24, 20, 15, 4, 6, 15, 24, 4, 6, 15, 24, 6","2":"46","3":"2, 4, 5, 6, 9, 10, 13, 16, 17, 19"}},{"t":"usc","label":"12 U.S.C. § 5553","url":"https://www.law.cornell.edu/uscode/text/12/5553","stext":{"head":"§5553. Preservation of existing contracts","paras":[[0,"This title,1 and regulations, orders, guidance, and interpretations prescribed, issued, or established by the Bureau, shall not be construed to alter or affect the applicability of any regulation, order, guidance, or interpretation prescribed, issued, and established by the Comptroller of the Currency or the Director of the Office of Thrift Supervision regarding the applicability of State law under Federal banking law to any contract entered into on or before July 21, 2010, by national banks, Federal savings associations, or subsidiaries thereof that are regulated and supervised by the Comptroller of the Currency or the Director of the Office of Thrift Supervision, respectively."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5553?type=usc&year=mostrecent&link-type=html"},"head":"§5553. Preservation of existing contracts","tname":"Banks and Banking","by":{"1":"17, 25","3":"11"}},{"t":"usc","label":"12 U.S.C. § 221","url":"https://www.law.cornell.edu/uscode/text/12/221","by":{"1":"31"}},{"t":"usc","label":"12 U.S.C. § 341","url":"https://www.law.cornell.edu/uscode/text/12/341","by":{"1":"28"}},{"t":"usc","label":"12 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/12/371","subs":["(a)"],"stext":{"head":"§371. Real estate loans","paras":[[0,"(a) Authorization to make real estate loans; orders, rules, and regulations of Comptroller of the Currency"],[0,"Any national banking association may make, arrange, purchase or sell loans or extensions of credit secured by liens on interests in real estate, subject to section 1828(o) of this title and such restrictions and requirements as the Comptroller of the Currency may prescribe by regulation or order."],[0,"(b) Eligibility for discount as commercial paper of notes representing loans financing construction of residential or farm buildings; prerequisites"],[0,"Notes representing loans made under this section to finance the construction of residential or farm buildings and having maturities not to exceed nine months shall be eligible for discount as commercial paper within the terms of the first paragraph of section 343 of this title if accompanied by a valid and binding agreement to advance the full amount of the loan upon the completion of the building entered into by an individual, partnership, association, or corporation acceptable to the discounting bank."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/371?type=usc&year=mostrecent&link-type=html"},"head":"§371. Real estate loans","tname":"Banks and Banking","by":{"1":"2","3":"14, 19"}},{"t":"usc","label":"15 U.S.C. § 1011","url":"https://www.law.cornell.edu/uscode/text/15/1011","by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 1012","url":"https://www.law.cornell.edu/uscode/text/15/1012","subs":["(b)"],"by":{"1":"29, 29"}},{"t":"usc","label":"12 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/12/1","by":{"1":"1"}},{"t":"usc","label":"12 U.S.C. § 24","url":"https://www.law.cornell.edu/uscode/text/12/24","stext":{"head":"§24. Corporate powers of associations","paras":[[0,"Upon duly making and filing articles of association and an organization certificate a national banking association shall become, as from the date of the execution of its organization certificate, a body corporate, and as such, and in the name designated in the organization certificate, it shall have power—"],[0,"First. To adopt and use a corporate seal."],[0,"Second. To have succession from February 25, 1927, or from the date of its organization if organized after February 25, 1927, until such time as it be dissolved by the act of its shareholders owning two-thirds of its stock, or until its franchise becomes forfeited by reason of violation of law, or until terminated by either a general or a special Act of Congress or until its affairs be placed in the hands of a receiver and finally wound up by him."],[0,"Third. To make contracts."],[0,"Fourth. To sue and be sued, complain and defend, in any court of law and equity, as fully as natural persons."],[0,"Fifth. To elect or appoint directors, and by its board of directors to appoint a president, vice president, cashier, and other officers, define their duties, require bonds of them and fix the penalty thereof, dismiss such officers or any of them at pleasure, and appoint others to fill their places."],[0,"Sixth. To prescribe, by its board of directors, bylaws not inconsistent with law, regulating the manner in which its stock shall be transferred, its directors elected or appointed, its officers appointed, its property transferred, its general business conducted, and the privileges granted to it by law exercised and enjoyed."],[0,"Seventh. To exercise by its board of directors or duly authorized officers or agents, subject to law, all such incidental powers as shall be necessary to carry on the business of banking; by discounting and negotiating promissory notes, drafts, bills of exchange, and other evidences of debt; by receiving deposits; by buying and selling exchange, coin, and bullion; by loaning money on personal security; and by obtaining, issuing, and circulating notes according to the provisions of title 62 of the Revised Statutes. The business of dealing in securities and stock by the association shall be limited to purchasing and selling such securities and stock without recourse, solely upon the order, and for the account of, customers, and in no case for its own account, and the association shall not underwrite any issue of securities or stock; Provided, That the association may purchase for its own account investment securities under such limitations and restrictions as the Comptroller of the Currency may by regulation prescribe. In no event shall the total amount of the investment securities of any one obligor or maker, held by the association for its own account, exceed at any time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund, except that this limitation shall not require any association to dispose of any securities lawfully held by it on August 23, 1935. As used in this section the term \"investment securities\" shall mean marketable obligations, evidencing indebtedness of any person, copartnership, association, or corporation in the form of bonds, notes and/or debentures commonly known as investment securities under such further definition of the term \"investment securities\" as may by regulation be prescribed by the Comptroller of the Currency. Except as hereinafter provided or otherwise permitted by law, nothing herein contained shall authorize the purchase by the association for its own account of any shares of stock of any corporation. The limitations and restrictions herein contained as to dealing in, underwriting and purchasing for its own account, investment securities shall not apply to obligations of the United States, or general obligations of any State or of any political subdivision thereof, or obligations of the Washington Metropolitan Area Transit Authority which are guaranteed by the Secretary of Transportation under section 9 of the National Capital Transportation Act of 1969, or obligations issued under authority of the Federal Farm Loan Act, as amended, or issued by the thirteen banks for cooperatives or any of them or the Federal Home Loan Banks, or obligations which are insured by the Secretary of Housing and Urban Development under title XI of the National Housing Act [12 U.S.C. 1749aaa et seq.] or obligations which are insured by the Secretary of Housing and Urban Development (hereinafter in this sentence referred to as the \"Secretary\") pursuant to section 207 of the National Housing Act [12 U.S.C. 1713], if the debentures to be issued in payment of such insured obligations are guaranteed as to principal and interest by the United States, or obligations, participations, or other instruments of or issued by the Federal National Mortgage Association, or the Government National Mortgage Association, or mortgages, obligations or other securities which are or ever have been sold by the Federal Home Loan Mortgage Corporation pursuant to section 305 or section 306 of the Federal Home Loan Mortgage Corporation Act [12 U.S.C. 1454 or 1455], or obligations of the Federal Financing Bank or obligations of the Environmental Financing Authority, or obligations or other instruments or securities of the Student Loan Marketing Association, or such obligations of any local public agency (as defined in section 110(h) of the Housing Act of 1949 [42 U.S.C. 1460(h)]) as are secured by an agreement between the local public agency and the Secretary in which the local public agency agrees to borrow from said Secretary, and said Secretary agrees to lend to said local public agency, monies in an aggregate amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay, when due, the interest on and all installments (including the final installment) of the principal of such obligations, which monies under the terms of said agreement are required to be used for such payments, or such obligations of a public housing agency (as defined in the United States Housing Act of 1937, as amended [42 U.S.C. 1437 et seq.]) as are secured (1) by an agreement between the public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of such obligations, monies in an amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay the principal of such obligations with interest to maturity thereon, which monies under the terms of said agreement are required to be used for the purpose of paying the principal of and the interest on such obligations at their maturity, (2) by a pledge of annual contributions under an annual contributions contract between such public housing agency and the Secretary if such contract shall contain the covenant by the Secretary which is authorized by subsection (g) of section 6 of the United States Housing Act of 1937, as amended [42 U.S.C. 1437d(g)], and if the maximum sum and the maximum period specified in such contract pursuant to said subsection 6(g) [42 U.S.C. 1437d(g)] shall not be less than the annual amount and the period for payment which are requisite to provide for the payment when due of all installments of principal and interest on such obligations, or (3) by a pledge of both annual contributions under an annual contributions contract containing the covenant by the Secretary which is authorized by section 6(g) of the United States Housing Act of 1937 [42 U.S.C. 1437d(g)], and a loan under an agreement between the local public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of the obligations involved, moneys in an amount which (together with any other moneys irrevocably committed under the annual contributions contract to the payment of principal and interest on such obligations) will suffice to provide for the payment when due of all installments of principal and interest on such obligations, which moneys under the terms of the agreement are required to be used for the purpose of paying the principal and interest on such obligations at their maturity: Provided, That in carrying on the business commonly known as the safe-deposit business the association shall not invest in the capital stock of a corporation organized under the law of any State to conduct a safe-deposit business in an amount in excess of 15 per centum of the capital stock of the association actually paid in and unimpaired and 15 per centum of its unimpaired surplus. The limitations and restrictions herein contained as to dealing in and underwriting investment securities shall not apply to obligations issued by the International Bank for Reconstruction and Development, the European Bank for Reconstruction and Development, the Inter-American Development Bank 1 Bank for Economic Cooperation and Development in the Middle East and North Africa,,2 the North American Development Bank, the Asian Development Bank, the African Development Bank, the Inter-American Investment Corporation, or the International Finance Corporation,,2 or obligations issued by any State or political subdivision or any agency of a State or political subdivision for housing, university, or dormitory purposes, which are at the time eligible for purchase by a national bank for its own account, nor to bonds, notes and other obligations issued by the Tennessee Valley Authority or by the United States Postal Service: Provided, That no association shall hold obligations issued by any of said organizations as a result of underwriting, dealing, or purchasing for its own account (and for this purpose obligations as to which it is under commitment shall be deemed to be held by it) in a total amount exceeding at any one time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation authorized to be created pursuant to title IX of the Housing and Urban Development Act of 1968 [42 U.S.C. 3931 et seq.], and may make investments in a partnership, limited partnership, or joint venture formed pursuant to section 907(a) or 907(c) of that Act [42 U.S.C. 3937(a) or 3937(c)]. Notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock issued by any State housing corporation incorporated in the State in which the association is located and may make investments in loans and commitments for loans to any such corporation: Provided, That in no event shall the total amount of such stock held for its own account and such investments in loans and commitments made by the association exceed at any time 5 per centum of its capital stock actually paid in and unimpaired plus 5 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation organized solely for the purpose of making loans to farmers and ranchers for agricultural purposes, including the breeding, raising, fattening, or marketing of livestock. However, unless the association owns at least 80 per centum of the stock of such agricultural credit corporation the amount invested by the association at any one time in the stock of such corporation shall not exceed 20 per centum of the unimpaired capital and surplus of the association: Provided further, That notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock of a bank insured by the Federal Deposit Insurance Corporation or a holding company which owns or controls such an insured bank if the stock of such bank or company is owned exclusively (except to the extent directors' qualifying shares are required by law) by depository institutions or depository institution holding companies (as defined in section 1813 of this title) and such bank or company and all subsidiaries thereof are engaged exclusively in providing services to or for other depository institutions, their holding companies, and the officers, directors, and employees of such institutions and companies, and in providing correspondent banking services at the request of other depository institutions or their holding companies (also referred to as a \"banker's bank\"), but in no event shall the total amount of such stock held by the association in any bank or holding company exceed at any time 10 per centum of the association's capital stock and paid in and unimpaired surplus and in no event shall the purchase of such stock result in an association's acquiring more than 5 per centum of any class of voting securities of such bank or company. The limitations and restrictions contained in this paragraph as to an association purchasing for its own account investment securities shall not apply to securities that (A) are offered and sold pursuant to section 4(5) of the Securities Act of 1933 (15 U.S.C. 77d(5)); 3 (B) are small business related securities (as defined in section 3(a)(53) of the Securities Exchange Act of 1934 [15 U.S.C. 78c(a)(53)]); or (C) are mortgage related securities (as that term is defined in section 3(a)(41) of the Securities Exchange Act of 1934 (15 U.S.C. 78c(a)(41)).4 The exception provided for the securities described in subparagraphs (A), (B), and (C) shall be subject to such regulations as the Comptroller of the Currency may prescribe, including regulations prescribing minimum size of the issue (at the time of initial distribution) or minimum aggregate sales prices, or both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/24?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§24. Corporate powers of associations","tname":"Banks and Banking","by":{"1":"2, 2","2":"5, 8, 20, 28","3":"1, 5, 19"}},{"t":"usc","label":"12 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/12/548","by":{"1":"28"}},{"t":"reg","label":"Designated Transfer Date, 75 Fed. Reg. 57,252","url":"https://www.govinfo.gov/link/fr/75/57252","by":{"1":"4"}},{"t":"reg","label":"69 Fed. Reg. 1904","url":"https://www.govinfo.gov/link/fr/69/1904","by":{"1":"4","2":"12, 32-33","3":"11"}},{"t":"reg","label":"76 Fed. Reg. 30,557","url":"https://www.govinfo.gov/link/fr/76/30557","by":{"1":"4, 5"}},{"t":"reg","label":"76 Fed. Reg. 43,549","url":"https://www.govinfo.gov/link/fr/76/43549","by":{"1":"6","2":"2, 12-13, 33-34, 46"}},{"t":"case","label":"Ass’n of Banks in Ins., Inc. v. Duryee","cite":"270 F.3d 397","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/270/397/","by":{"2":"40"}},{"t":"case","label":"Bank One v. Guttau","cite":"190 F.3d 844","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/190/844/","by":{"2":"36"}},{"t":"case","label":"Barefoot v. Estelle","cite":"463 U.S. 880","y":1983,"id":"1982/82-6080","sc":1,"sum":"The Supreme Court held that, in denying the stay of execution, the U.S. Court of Appeals for the Fifth Circuit necessarily examined the decision of the district court on the merits of the case. Although the Court of Appeals may not formally affirm the judgment of the lower court, the denial of the stay of execution serves the same purpose.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Beneficial Nat’l Bank v. Anderson","cite":"539 U.S. 1","y":2003,"id":"2002/02-306","sc":1,"sum":"The Court held that the National Bank Act preempted the state-law claim and provided the exclusive cause of action for usury claims against national banks. Thus, the claim arose under federal law.","sumSrc":"Oyez","by":{"2":"1"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"29"}},{"t":"case","label":"Cooper Indus., Inc. v. Aviall Servs.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Deutsche Bank Nat’l Tr. Co. v. Barclays Bank PLC","cite":"140 N.E.3d 511","y":2019,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.3d/140/511/","by":{"2":"19"}},{"t":"case","label":"Easton v. Iowa","cite":"188 U.S. 220","y":1903,"id":"scdb/1902-051","sc":1,"sum":"Congress having power to create a system of national banks, is the judge as to the extent of the powers which should he conferred upon such banks, and has the sole power to regulate and control the exercise of their operations. Congress having dealt directly with the insolvency of national banks by giving control to the Secretary of the Treasury and the Comptroller of the Currency, who are authorized to suspendthe …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22, 26, 28, 32"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Farmers’ & Mechs.’ Nat’l Bank v. Dearing","cite":"91 U.S. 29","y":1875,"id":"scdb/1875-007","sc":1,"by":{"2":"2, 21-23, 27"}},{"t":"case","label":"Fid. Fed. Sav. & Loan Ass’n v. de la Cuesta","cite":"458 U.S. 141","y":1982,"id":"1981/81-750","sc":1,"op":1,"sum":"The Board's due-on-sale regulation pre-empts conflicting state limitations on the due-on-sale practices of federal savings and loan associations, and thus bars application of the Wellenkamp rule to such associations.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22, 45","3":"12"}},{"t":"case","label":"First Nat’l Bank v. Kentucky","cite":"76 U.S. 353","y":1870,"id":"scdb/1869-077","sc":1,"sum":"The act of Congress establishing the National banks, enacts:","sumSrc":"Headnote (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Gallardo ex rel. Vassallo v. Marstiller","cite":"596 U.S. 420","y":2022,"id":"2021/20-1263","sc":1,"sum":"The Medicaid Act permits a State to seek reimbursement from settlement payments allocated for future medical care.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"44"}},{"t":"case","label":"Halberstam v. Welch","cite":"705 F.2d 472","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/705/472/","by":{"2":"35"}},{"t":"case","label":"Ilan Props., Inc. v. Benishai","cite":"166 N.Y.S.3d 532","y":2022,"court":"App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.3d/166/532/","by":{"2":"19"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich LPA","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Marquette Nat’l Bank of Minneapolis v. First Omaha Serv. Corp.","cite":"439 U.S. 299","y":1978,"id":"1978/77-1265","sc":1,"sum":"Section 85 permits Omaha Bank to charge its Minnesota BankAmericard customers the higher interest rate that is sanctioned by Nebraska law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5-6, 20, 27"}},{"t":"case","label":"Mass. Bankers Ass’n, Inc. v. Bowler","cite":"392 F. Supp. 2d 24","y":2005,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/392/24/","by":{"2":"40"}},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"op":2,"ar":2,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"2":"14, 23, 26"}},{"t":"case","label":"Merck Sharp & Dohme Corp. v. Albrecht","cite":"139 S. Ct. 1668","y":2019,"id":"2018/17-290","sc":1,"sum":"“Clear evidence” that the FDA would not have approved a change to a drug’s label—thus pre-empting a state-law failure-to-warn claim—is evidence showing that the drug manufacturer fully informed the FDA of the justifications for the warning required by state law and that the FDA, in turn, informed the drug manufacturer that the FDA would not approve a change to the drug’s label to include that warning; the question of agency disapproval is primarily one of law for a judge to decide.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"44","3":"18"}},{"t":"case","label":"Parks v. MBNA Am. Bank, N.A.","cite":"278 P.3d 1193","y":2012,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/278/1193/","by":{"2":"50"}},{"t":"case","label":"People v. Franklin Nat’l Bank of Franklin Square","cite":"113 N.E.2d 796","y":1953,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/113/796/","by":{"2":"42"}},{"t":"case","label":"Rose v. Chase Bank USA, N.A.","cite":"513 F.3d 1032","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/513/1032/","by":{"2":"36"}},{"t":"case","label":"Saslow v. Cephas","cite":"603 N.Y.S.2d 460","y":1993,"court":"App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/603/460/","by":{"2":"30"}},{"t":"case","label":"Slack v. McDaniel","cite":"529 U.S. 473","y":2000,"id":"1999/98-6322","sc":1,"sum":"The Court held that a federal habeas corpus petition filed by a state prisoner, after an initial petition was dismissed without adjudication on the merits, does not constitute a \"second or successive\" petition, subject to dismissal for abuse of writ.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"SPGGC, LLC v. Ayotte","cite":"488 F.3d 525","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/488/525/","by":{"2":"36"}},{"t":"case","label":"Talbott v. Bd. of Comm’rs","cite":"139 U.S. 438","y":1891,"id":"scdb/1890-186","sc":1,"sum":"The territories possess the same power of taxing national banks which States enjoy.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Twitter, Inc. v. Taamneh","cite":"598 U.S. 471","y":2023,"id":"2022/21-1496","sc":1,"sum":"Plaintiffs’ allegations that the social-media-company defendants aided and abetted ISIS in its terrorist attack on a nightclub in Istanbul, Turkey fail to state a claim under 18 U. S. C. §2333(d)(2).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"35"}},{"t":"case","label":"Waite v. Dowley","cite":"94 U.S. 527","y":1876,"id":"scdb/1876-165","sc":1,"sum":"On the 9th of November, 1865, the legislature of Vermont-passed the following act. Acts of 1865, p. 17.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"Wichita Royalty Co. v. City Nat’l Bank of Wichita Falls","cite":"306 U.S. 103","y":1939,"id":"scdb/1938-111","sc":1,"sum":"1. The opinion of the Supreme Court of Texas at an earlier stage of this case, defining the liability of a bank for trust-funds transferred by a trustee from the trust account to a personal account, and checked out and misappropriated by him after the bank had accepted payment of his personal debts to the bank or an officer thereof, with notice that the payments had their source in trust funds, was not modified by …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"sum":"The Court held that under federal law, as amended by the AEDPA, \"a 'failure to develop' a claim's factual basis in state court proceedings is not established unless there is lack of diligence, or some greater fault, attributable to the prisoner or his counsel.\" Justice Kennedy wrote for the Court that \"comity is not served by saying a prisoner 'has failed to develop the factual basis of a claim' where he was unable to develop his claim in state court despite diligent effort.","sumSrc":"Oyez","by":{"2":"35, 39"}},{"t":"usc","label":"15 U.S.C. § 1639","url":"https://www.law.cornell.edu/uscode/text/15/1639","by":{"2":"48"}},{"t":"law","label":"Justice Against Sponsors of Terrorism Act, Pub. L. No. 114-222","url":"https://www.govinfo.gov/link/plaw/114/public/222","by":{"2":"35"}},{"t":"reg","label":"7 C.F.R. § 3555.252","url":"https://www.ecfr.gov/current/title-7/section-3555.252","by":{"2":"9"}},{"t":"reg","label":"12 C.F.R. § 1.1","url":"https://www.ecfr.gov/current/title-12/section-1.1","by":{"2":"6"}},{"t":"reg","label":"12 C.F.R. § 7.4006","url":"https://www.ecfr.gov/current/title-12/section-7.4006","by":{"2":"47"}},{"t":"reg","label":"24 C.F.R. § 200.84","url":"https://www.ecfr.gov/current/title-24/section-200.84","by":{"2":"9"}},{"t":"reg","label":"48 Fed. Reg. 40698","url":"https://www.govinfo.gov/link/fr/48/40698","by":{"2":"12"}},{"t":"reg","label":"78 Fed. Reg. 4726","url":"https://www.govinfo.gov/link/fr/78/4726","by":{"2":"10"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Bowler v. Hawke","cite":"320 F.3d 59","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/320/59/","by":{"3":"3, 15, 18"}},{"t":"case","label":"California Division of Labor Standards Enforcement v. Dillingham Construction, N.A.","cite":"519 U.S. 316","y":1997,"id":"1996/95-789","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that California's prevailing wage law does not \"relate to\" employee benefit plans, and thus is not preempted by the Employee Retirement Income Security Act of 1974.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Costello v. BeavEx, Inc.","cite":"810 F.3d 1045","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1045/","by":{"3":"13"}},{"t":"case","label":"Dilts v. Penske Logistics, LLC","cite":"769 F.3d 637","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/769/637/","by":{"3":"16"}},{"t":"case","label":"Federal National Mortgage Association v. Lefkowitz","cite":"390 F. Supp. 1364","y":1975,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./390/1364/","op":1,"by":{"3":"14"}},{"t":"case","label":"Helix Energy Solutions Group v. Hewitt","cite":"598 U.S. 39","y":2023,"id":"2022/21-984","sc":1,"sum":"Respondent Hewitt was not an executive exempt from the FLSA’s overtime pay guarantee; daily-rate workers, of whatever income level, qualify as paid on a salary basis only if the conditions set out in 29 CFR §541.604(b) are met.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"3"}},{"t":"case","label":"Irwin v. Gavit","cite":"268 U.S. 161","y":1925,"id":"scdb/1924-129","sc":1,"sum":"1. A will provided that the income from a fund in trust should be applied to the education and support of the testator's granddaughter so far as the trustees deemed proper and that the balance of it should be divided into two equal parts one of which should be paid to the plaintiff in equal, quarter-yearly instalments during his life. On the granddaughter's reaching the age of twenty-one or dying, the fund was to go …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Montalvo v. Spirit Airlines","cite":"508 F.3d 464","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/508/464/","by":{"3":"15"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"ar":2,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"New York State Conference of Blue Cross & Blue Shield Plans v. Travelers Insurance Co.","cite":"514 U.S. 645","y":1995,"id":"1994/93-1408","sc":1,"sum":"New York's surcharge provisions do not \"relate to\" employee benefit plans within the meaning of § 514(a) and, thus, are not pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Northwest, Inc. v. Ginsberg","cite":"572 U.S. 273","y":2014,"id":"2013/12-462","sc":1,"sum":"The Court held that the Airline Deregulation Act preempts claims arising from a frequent flier complaint based on price, route, or air carrier service.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"3":"3, 10"}},{"t":"case","label":"- iv Rutledge v. Pharmaceutical Care Management Association","cite":"592 U.S. 80","y":2020,"url":"https://supreme.justia.com/cases/federal/us/592/80/","sc":1,"by":{"3":"15"}},{"t":"case","label":"Smiley v. Citibank (South Dakota), N.A.","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"op":1,"sum":"The Court held that the National Bank Act of 1864 authorizes such charges because a regulation adopted by the Comptroller of the Currency, which defined interest to include late-payment fees, was a reasonable interpretation of the act and entitled to deference.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Ward v. United Airlines, Inc.","cite":"986 F.3d 1234","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/986/1234/","sum":"Finding no preemption where the defendant “presented no evidence” of “significant impact”.","sumSrc":"brief:3","by":{"3":"15"}},{"t":"case","label":"Wos v. E.M.A. ex rel. Johnson","cite":"568 U.S. 627","y":2013,"id":"2012/12-98","sc":1,"sum":"The Court held that federal law preempts North Carolina's state law regarding reimbursement of medical expenses from a patient's settlement.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"usc","label":"12 U.S.C. § 21","url":"https://www.law.cornell.edu/uscode/text/12/21","by":{"3":"13"}},{"t":"usc","label":"12 U.S.C. § 36","url":"https://www.law.cornell.edu/uscode/text/12/36","by":{"3":"1, 5, 6, 19"}},{"t":"usc","label":"12 U.S.C. § 85","url":"https://www.law.cornell.edu/uscode/text/12/85","by":{"3":"13"}},{"t":"usc","label":"15 U.S.C. § 1639d","url":"https://www.law.cornell.edu/uscode/text/15/1639d","stext":{"head":"§1639d. Escrow or impound accounts relating to certain consumer credit transactions","paras":[[0,"(a) In general"],[0,"Except as provided in subsection (b), (c), (d), or (e), a creditor, in connection with the consummation of a consumer credit transaction secured by a first lien on the principal dwelling of the consumer, other than a consumer credit transaction under an open end credit plan or a reverse mortgage, shall establish, before the consummation of such transaction, an escrow or impound account for the payment of taxes and hazard insurance, and, if applicable, flood insurance, mortgage insurance, ground rents, and any other required periodic payments or premiums with respect to the property or the loan terms, as provided in, and in accordance with, this section."],[0,"(b) When required"],[0,"No impound, trust, or other type of account for the payment of property taxes, insurance premiums, or other purposes relating to the property may be required as a condition of a real property sale contract or a loan secured by a first deed of trust or mortgage on the principal dwelling of the consumer, other than a consumer credit transaction under an open end credit plan or a reverse mortgage, except when—"],[1,"(1) any such impound, trust, or other type of escrow or impound account for such purposes is required by Federal or State law;"],[1,"(2) a loan is made, guaranteed, or insured by a State or Federal governmental lending or insuring agency;"],[1,"(3) the transaction is secured by a first mortgage or lien on the consumer's principal dwelling having an original principal obligation amount that—"],[2,"(A) does not exceed the amount of the maximum limitation on the original principal obligation of mortgage in effect for a residence of the applicable size, as of the date such interest rate set, pursuant to the sixth sentence of section 1454(a)(2) of title 12, and the annual percentage rate will exceed the average prime offer rate as defined in section 1639c of this title by 1.5 or more percentage points; or"],[2,"(B) exceeds the amount of the maximum limitation on the original principal obligation of mortgage in effect for a residence of the applicable size, as of the date such interest rate set, pursuant to the sixth sentence of section 1454(a)(2) of title 12, and the annual percentage rate will exceed the average prime offer rate as defined in section 1639c of this title by 2.5 or more percentage points; or"],[1,"(4) so required pursuant to regulation."],[0,"(c) Exemptions"],[0,"(1) In general"],[1,"The Bureau may, by regulation, exempt from the requirements of subsection (a) a creditor that—"],[2,"(A) operates in rural or underserved areas;"],[2,"(B) together with all affiliates, has total annual mortgage loan originations that do not exceed a limit set by the Bureau;"],[2,"(C) retains its mortgage loan originations in portfolio; and"],[2,"(D) meets any asset size threshold and any other criteria the Bureau may establish, consistent with the purposes of this part."],[0,"(2) Treatment of loans held by smaller institutions"],[1,"The Bureau shall, by regulation, exempt from the requirements of subsection (a) any loan made by an insured depository institution or an insured credit union secured by a first lien on the principal dwelling of a consumer if—"],[2,"(A) the insured depository institution or insured credit union has assets of $10,000,000,000 or less;"],[2,"(B) during the preceding calendar year, the insured depository institution or insured credit union and its affiliates originated 1,000 or fewer loans secured by a first lien on a principal dwelling; and"],[2,"(C) the transaction satisfies the criteria in sections 1026.35(b)(2)(iii)(A), 1026.35(b)(2)(iii)(D), and 1026.35(b)(2)(v) of title 12, Code of Federal Regulations, or any successor regulation."],[0,"(d) Duration of mandatory escrow or impound account"],[0,"An escrow or impound account established pursuant to subsection (b) shall remain in existence for a minimum period of 5 years, beginning with the date of the consummation of the loan, unless and until—"],[1,"(1) such borrower has sufficient equity in the dwelling securing the consumer credit transaction so as to no longer be required to maintain private mortgage insurance;"],[1,"(2) such borrower is delinquent;"],[1,"(3) such borrower otherwise has not complied with the legal obligation, as established by rule; or"],[1,"(4) the underlying mortgage establishing the account is terminated."],[0,"(e) Limited exemptions for loans secured by shares in a cooperative or in which an association must maintain a master insurance policy"],[0,"Escrow accounts need not be established for loans secured by shares in a cooperative. Insurance premiums need not be included in escrow accounts for loans secured by dwellings or units, where the borrower must join an association as a condition of ownership, and that association has an obligation to the dwelling or unit owners to maintain a master policy insuring the dwellings or units."],[0,"(f) Clarification on escrow accounts for loans not meeting statutory test"],[0,"For mortgages not covered by the requirements of subsection (b), no provision of this section shall be construed as precluding the establishment of an impound, trust, or other type of account for the payment of property taxes, insurance premiums, or other purposes relating to the property—"],[1,"(1) on terms mutually agreeable to the parties to the loan;"],[1,"(2) at the discretion of the lender or servicer, as provided by the contract between the lender or servicer and the borrower; or"],[1,"(3) pursuant to the requirements for the escrowing of flood insurance payments for regulated lending institutions in section 102(d) of the Flood Disaster Protection Act of 1973 [42 U.S.C. 4012a(d)]."],[0,"(g) Administration of mandatory escrow or impound accounts"],[0,"(1) In general"],[1,"Except as may otherwise be provided for in this subchapter or in regulations prescribed by the Bureau, escrow or impound accounts established pursuant to subsection (b) shall be established in a federally insured depository institution or credit union."],[0,"(2) Administration"],[1,"Except as provided in this section or regulations prescribed under this section, an escrow or impound account subject to this section shall be administered in accordance with—"],[2,"(A) the Real Estate Settlement Procedures Act of 1974 [12 U.S.C. 2601 et seq.] and regulations prescribed under such Act;"],[2,"(B) the Flood Disaster Protection Act of 1973 and regulations prescribed under such Act; and"],[2,"(C) the law of the State, if applicable, where the real property securing the consumer credit transaction is located."],[0,"(3) Applicability of payment of interest"],[1,"If prescribed by applicable State or Federal law, each creditor shall pay interest to the consumer on the amount held in any impound, trust, or escrow account that is subject to this section in the manner as prescribed by that applicable State or Federal law."],[0,"(4) Penalty coordination with RESPA"],[1,"Any action or omission on the part of any person which constitutes a violation of the Real Estate Settlement Procedures Act of 1974 or any regulation prescribed under such Act for which the person has paid any fine, civil money penalty, or other damages shall not give rise to any additional fine, civil money penalty, or other damages under this section, unless the action or omission also constitutes a direct violation of this section."],[0,"(h) Disclosures relating to mandatory escrow or impound account"],[0,"In the case of any impound, trust, or escrow account that is required under subsection (b), the creditor shall disclose by written notice to the consumer at least 3 business days before the consummation of the consumer credit transaction giving rise to such account or in accordance with timeframes established in prescribed regulations the following information:"],[1,"(1) The fact that an escrow or impound account will be established at consummation of the transaction."],[1,"(2) The amount required at closing to initially fund the escrow or impound account."],[1,"(3) The amount, in the initial year after the consummation of the transaction, of the estimated taxes and hazard insurance, including flood insurance, if applicable, and any other required periodic payments or premiums that reflects, as appropriate, either the taxable assessed value of the real property securing the transaction, including the value of any improvements on the property or to be constructed on the property (whether or not such construction will be financed from the proceeds of the transaction) or the replacement costs of the property."],[1,"(4) The estimated monthly amount payable to be escrowed for taxes, hazard insurance (including flood insurance, if applicable) and any other required periodic payments or premiums."],[1,"(5) The fact that, if the consumer chooses to terminate the account in the future, the consumer will become responsible for the payment of all taxes, hazard insurance, and flood insurance, if applicable, as well as any other required periodic payments or premiums on the property unless a new escrow or impound account is established."],[1,"(6) Such other information as the Bureau determines necessary for the protection of the consumer."],[0,"(i) Definitions"],[0,"For purposes of this section, the following definitions shall apply:"],[0,"(1) Flood insurance"],[1,"The term \"flood insurance\" means flood insurance coverage provided under the national flood insurance program pursuant to the National Flood Insurance Act of 1968 [42 U.S.C. 4001 et seq.]."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1639d?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1639d. Escrow or impound accounts relating to certain consumer credit transactions","tname":"Commerce and Trade","by":{"3":"20"}},{"t":"reg","label":"Preemption Opinion, 66 Fed. Reg. 23977","url":"https://www.govinfo.gov/link/fr/66/23977","by":{"3":"17"}},{"t":"reg","label":"Preemption Opinion, 66 Fed. Reg. 51502","url":"https://www.govinfo.gov/link/fr/66/51502","by":{"3":"16, 17"}}]};